package com.himeros.interaction;import com.himeros.shared.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.UUID;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/interactions")public class InteractionController{private final InteractionService service;private final CurrentUser current;public InteractionController(InteractionService service,CurrentUser current){this.service=service;this.current=current;}@PostMapping("/{targetUserId}")InteractionService.Result interact(@PathVariable UUID targetUserId,@Valid@RequestBody Request r){return service.interact(current.id(),targetUserId,r.type());}public record Request(@NotBlank @Pattern(regexp="(?i)LIKE|PASS|SUPER_LIKE")String type){}}
